-- tryHimandsee ministries - Resource Directory
-- Run this once in the Cloudflare D1 console for the tryhimandsee-db database.

CREATE TABLE IF NOT EXISTS resources (
  id           TEXT PRIMARY KEY,
  category     TEXT NOT NULL,
  name         TEXT NOT NULL,
  description  TEXT,
  address      TEXT,
  phone        TEXT,
  website      TEXT,
  hours        TEXT,
  notes        TEXT,
  sort_order   INTEGER NOT NULL DEFAULT 0,
  is_active    INTEGER NOT NULL DEFAULT 1,
  created_at   TEXT NOT NULL,
  updated_at   TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_resources_category_sort
  ON resources (category, sort_order);

